$ErrorActionPreference='Stop';
$out=@();
foreach($f in @('E:\WebAIBridge\app\worker.js','E:\WebAIBridge\app\server.js','E:\WebAIBridge\app\supervisor-watchdog.js')){
  if(Test-Path $f){
    $m=Select-String -Path $f -Pattern @('Managed agent High mode is not confirmed','managed_assignment_high_race','ensureHighMode','highModeStrategy','Высокий|High') -SimpleMatch -CaseSensitive:$false | Select-Object LineNumber,Line;
    $out += [pscustomobject]@{path=$f;exists=$true;matches=@($m)}
  } else {
    $out += [pscustomobject]@{path=$f;exists=$false;matches=@()}
  }
}
$out | ConvertTo-Json -Depth 5 -Compress
